import{describe,it,expect}from"vitest";import{prahars,musicologyPillars,ragas,getRagaById,getRagasByPrahar,calculateClockAngle,filterRagas}from"../../frontend/ragas-time-explainer/ragas-time-explainer.js";const REQUIRED_RAGA_FIELDS=["id","name","praharId","timePeriod","thaat","vadi","samvadi","moodRasa","swaraStructure","textDescription","icon"];describe("Samaya Chakra & Prahars Clock Math",()=>{it("contains 8 Prahars spanning the full 24-hour solar cycle",()=>{expect(prahars.length).toBe(8)}),it("calculates correct clock angles for 8 Prahars",()=>{expect(calculateClockAngle(0,8)).toBe(0),expect(calculateClockAngle(2,8)).toBe(90),expect(calculateClockAngle(4,8)).toBe(180),expect(calculateClockAngle(6,8)).toBe(270)})}),describe("Ragas Dataset Integrity & Time-of-Day Associations",()=>{it("contains at least 5 sourced ragas with time associations (contains 6)",()=>{expect(ragas.length).toBeGreaterThanOrEqual(5)}),it("every raga contains required fields with valid musicological text",()=>{ragas.forEach((e,a)=>{REQUIRED_RAGA_FIELDS.forEach(t=>{expect(e,`Raga at index ${a} missing field ${t}`).toHaveProperty(t),expect(typeof e[t]).toBe("string"),expect(e[t].trim().length).toBeGreaterThan(0)})})}),it("all raga IDs are unique",()=>{const e=ragas.map(e=>e.id);expect(new Set(e).size).toBe(e.length)}),it("relies strictly on original text descriptions (no copyrighted audio/notation URLs)",()=>{ragas.forEach(e=>{expect(e.textDescription).toBeDefined(),expect(e.textDescription.length).toBeGreaterThan(20),expect(e.textDescription.toLowerCase()).not.toContain(".mp3"),expect(e.textDescription.toLowerCase()).not.toContain(".wav")})})}),describe("Raga Query & Filter Helpers",()=>{it("retrieves raga profile by ID or name",()=>{const e=getRagaById("raga-bhairav");expect(e).toBeDefined(),expect(e.name).toBe("Raga Bhairav");const a=getRagaById("Yaman");expect(a).toBeDefined(),expect(a.id).toBe("raga-yaman")}),it("retrieves ragas by Prahar ID",()=>{const e=getRagasByPrahar("p1");expect(e.length).toBeGreaterThan(0),expect(e[0].id).toBe("raga-bhairav");const a=getRagasByPrahar("p5");expect(a.length).toBeGreaterThan(0),expect(a[0].id).toBe("raga-yaman")}),it("filters ragas by search query (e.g. Komal Re or Midnight)",()=>{const e=filterRagas("Komal Re");expect(e.length).toBeGreaterThan(0);const a=filterRagas("Midnight");expect(a.length).toBeGreaterThan(0)}),it("returns empty array when search query matches nothing",()=>{const e=filterRagas("NonExistentRagaXYZ");expect(e).toEqual([])})});